Security review of a pending change. The diff is supplied inline; review it as written and do not modify any file. Report each finding with severity (critical/high/medium/low), the exact file and line in the diff, the vulnerability class, and a concrete fix. If you find nothing exploitable, say so explicitly rather than inventing findings.

```diff
diff --git a/cli-go/internal/serve/kanban_note.go b/cli-go/internal/serve/kanban_note.go
--- a/cli-go/internal/serve/kanban_note.go
+++ b/cli-go/internal/serve/kanban_note.go
@@ -1,3 +1,68 @@
+func handleKanbanNote(cfg Config) jsonrpc.Handler {
+	return func(ctx context.Context, raw json.RawMessage) (any, error) {
+		var p struct {
+			Project string `json:"project"`
+			ID      string `json:"id"`
+			Note    string `json:"note"`
+		}
+		dec := json.NewDecoder(bytes.NewReader(raw))
+		dec.DisallowUnknownFields()
+		if err := dec.Decode(&p); err != nil {
+			return nil, jsonrpc.InvalidParams(err)
+		}
+		if p.Project == "" {
+			return nil, jsonrpc.InvalidParams(errors.New("project required"))
+		}
+		if err := pathsafe.ValidateProjectSlug(p.Project); err != nil {
+			return nil, jsonrpc.InvalidParams(err)
+		}
+		if !kanbanIDRe.MatchString(p.ID) {
+			return nil, jsonrpc.InvalidParams(errors.New("bad id"))
+		}
+		if len(p.Note) > 4096 || strings.ContainsAny(p.Note, "\r\n\x00") {
+			return nil, jsonrpc.InvalidParams(errors.New("bad note"))
+		}
+		board := filepath.Join(cfg.StateDir, "projects", p.Project, "kanban.md")
+		unlock, err := lockfile.Acquire(board + ".lock")
+		if err != nil {
+			return nil, jsonrpc.Internal(err)
+		}
+		defer unlock()
+		if err := kanban.AppendNote(board, p.ID, p.Note); err != nil {
+			return nil, jsonrpc.Internal(err)
+		}
+		slog.Info("kanban note appended", "project", p.Project, "id", p.ID, "bytes", len(p.Note))
+		return map[string]bool{"ok": true}, nil
+	}
+}
+
+var kanbanIDRe = regexp.MustCompile(`^K-[0-9]{1,6}$`)
```
